//! Repository for EmployeeTax entities
//!
//! Originally generated by metaphor-schema; now **user-owned** — this exact path is declared under
//! `user_owned` in `metaphor.codegen.yaml`, so the generator skips it wholesale. The custom method
//! below holds the hand-written PTKP override read (4-layer rule: services orchestrate, repos hold
//! SQL).
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<EmployeeTax, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use chrono::NaiveDate;
use uuid::Uuid;
use sqlx::{FromRow, PgPool};

use backbone_orm::company_scope;

use crate::domain::entity::{EmployeeTax, PtkpTier, TerCategory};

/// Table name for EmployeeTax entities
pub const TABLE_NAME: &str = "employee.employee_taxes";

/// Repository for EmployeeTax entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct EmployeeTaxRepository(
    backbone_orm::GenericCrudRepository<EmployeeTax, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for EmployeeTaxRepository {
    type Target = backbone_orm::GenericCrudRepository<EmployeeTax, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl EmployeeTaxRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// Hand-written PTKP override read. Lives here (not in the query service) per the module's 4-layer
/// rule: services orchestrate, repositories hold the SQL.
impl EmployeeTaxRepository {
    /// The manual `ptkp_override` for `employee_id`, if one is set.
    ///
    /// Returns `None` when there is no tax row OR the row's `ptkp_override` is NULL — both mean
    /// "derive from dependents". Returns `Some(tier)` only when an explicit override is stored, in
    /// which case the caller MUST honour it (override wins).
    ///
    /// Read-only, company-scoped via `fetch_optional_scalar_scoped` (RLS fence, ADR-0008). The
    /// nullable `ptkp_tier` column is decoded as `Option<PtkpTier>`; `flatten` collapses the outer
    /// row-presence `Option` with the inner nullability into a single "is there an override".
    pub async fn ptkp_override_for(
        &self,
        pool: &PgPool,
        employee_id: Uuid,
    ) -> Result<Option<PtkpTier>, sqlx::Error> {
        let override_: Option<Option<PtkpTier>> = company_scope::fetch_optional_scalar_scoped(
            pool,
            sqlx::query_scalar(
                r#"SELECT ptkp_override FROM employee.employee_taxes
                   WHERE employee_id = $1
                     AND (metadata->>'deleted_at') IS NULL
                   LIMIT 1"#,
            )
            .bind(employee_id),
        )
        .await?;
        Ok(override_.flatten())
    }

    /// The statutory-relevant columns across `employee_taxes` / `employee_bpjs` / `employments` for
    /// `employee_id`: `(npwp_number, bpjs_kesehatan_family, join_date)`.
    ///
    /// One round-trip via correlated subqueries anchored on the employee row — each subquery picks
    /// the single relevant column from its table, so a missing bpjs/employment row degrades
    /// gracefully (that column comes back NULL) instead of dropping the whole bundle, and duplicate
    /// rows (a data error) collapse via `LIMIT 1` per subquery rather than multiplying the join. The
    /// `join_date` subquery picks the earliest (first join) — the tenure anchor for THR.
    ///
    /// Returns `None` only when the employee itself does not exist (or is out of the RLS scope). Read-
    /// only, company-scoped via `fetch_optional_scoped` (RLS fence, ADR-0008); `employee_id` is a
    /// globally unique FK so the `WHERE employee_id = $1` filter plus the task-local scope isolate it.
    pub async fn statutory_row_for(
        &self,
        pool: &PgPool,
        employee_id: Uuid,
    ) -> Result<Option<StatutoryRow>, sqlx::Error> {
        let row: Option<StatutoryRow> = company_scope::fetch_optional_scoped(
            pool,
            sqlx::query_as(
                r#"SELECT
                     (SELECT t.npwp_number
                        FROM employee.employee_taxes t
                        WHERE t.employee_id = e.id AND (t.metadata->>'deleted_at') IS NULL
                        LIMIT 1) AS npwp_number,
                     (SELECT t.ter_category
                        FROM employee.employee_taxes t
                        WHERE t.employee_id = e.id AND (t.metadata->>'deleted_at') IS NULL
                        LIMIT 1) AS ter_category,
                     (SELECT b.bpjs_kesehatan_family
                        FROM employee.employee_bpjs b
                        WHERE b.employee_id = e.id AND (b.metadata->>'deleted_at') IS NULL
                        LIMIT 1) AS bpjs_kesehatan_family,
                     (SELECT em.join_date
                        FROM employee.employments em
                        WHERE em.employee_id = e.id AND (em.metadata->>'deleted_at') IS NULL
                        ORDER BY em.join_date
                        LIMIT 1) AS join_date
                   FROM employee.employees e
                   WHERE e.id = $1 AND (e.metadata->>'deleted_at') IS NULL
                   LIMIT 1"#,
            )
            .bind(employee_id),
        )
        .await?;
        Ok(row)
    }
}

/// The statutory-relevant slice read by [`EmployeeTaxRepository::statutory_row_for`]. Each field is
/// nullable because each underlying row is optional for a given employee.
#[derive(Debug, Default, Clone, FromRow)]
pub struct StatutoryRow {
    pub npwp_number: Option<String>,
    pub ter_category: Option<TerCategory>,
    pub bpjs_kesehatan_family: Option<i32>,
    pub join_date: Option<NaiveDate>,
}

backbone_core::impl_crud_repository!(EmployeeTaxRepository, EmployeeTax, soft_delete);
